Uint8List _mascara(int w, int h) {
  final m = Uint8List(w * h);
  for (var y = 0; y < h; y++) {
    for (var x = 0; x < w; x++) {
      final borde = x == 0 || y == 0 || x == w - 1 || y == h - 1;
      if (borde || (x * 7 + y * 3) % 11 < 4 || x == w ~/ 2) m[y * w + x] = 1;
    }
  }
  return m;
}

void main() {
  test('normalizarLetra da exactamente lo mismo que el preprocesamiento de Python', () {
    _esperado.forEach((dims, esperado) {
      final (w, h) = dims;
      final r = AnalizadorEscritura.normalizarLetra(_mascara(w, h), w, h);
      expect(r.length, 28 * 28);
      for (var i = 0; i < r.length; i++) {
        expect(r[i], closeTo(esperado[i] / 10000, 1e-3), reason: 'letra ${w}x$h, píxel $i');
      }
    });
  });

  test('recortesDeLetras devuelve letras de 28x28 en [0,1] sobre la hoja sintética', () {
    final letras = AnalizadorEscritura.recortesDeLetras(hojaSintetica(irregular: false));
    expect(letras.length, greaterThanOrEqualTo(minLetrasParaInversiones));
    for (final l in letras) {
      expect(l.length, 28 * 28);
      expect(l.every((v) => v >= 0 && v <= 1), isTrue);
      expect(l.reduce((a, b) => a + b), greaterThan(0)); // no hay recortes vacíos
    }
  });

  group('señal de letras en espejo', () {
    final medidas = AnalizadorEscritura.medir(hojaSintetica(irregular: false));

    test('muchas letras en espejo suben el riesgo y aparece la frase', () {
      final sin = interpretar(medidas, letras: const ResultadoLetras(letras: 40, invertidas: 0));
      final con = interpretar(medidas, letras: const ResultadoLetras(letras: 40, invertidas: 8));
      expect(con.puntaje, greaterThan(sin.puntaje));
      expect(con.senales.join(), contains('espejo'));
      expect(sin.senales.join(), isNot(contains('varias letras escritas en espejo')));
    });

    test('con pocas letras sueltas no se usa la señal y se avisa', () {
      final r = interpretar(medidas, letras: const ResultadoLetras(letras: 5, invertidas: 5));
      final base = interpretar(medidas);
      expect(r.puntaje, base.puntaje);
      expect(r.senales.join(), contains('pocas letras sueltas'));
    });
  });
}
